import AppKit

/// A reusable view whose corners stay optically concentric with the rounded
/// ancestor that contains it. `cornerConfiguration` is READ-ONLY on NSView, so a
/// custom view declares its corner style by OVERRIDING the getter — never by
/// assignment. AppKit reads the getter and recomputes `effectiveCornerRadii`.
@MainActor final class ConcentricView: NSView {
    override var cornerConfiguration: NSViewCornerConfiguration? {
        .uniformCorners(radius: .containerConcentric)
    }
}

/// A card presenting content inside a Liquid Glass container. The header strip at
/// the top uses concentric corners to track the outer card radius automatically.
@MainActor final class CardView: NSView {

    private let glassContainer = NSGlassEffectView()
    private let headerStrip = ConcentricView()   // concentric via overridden getter
    private let contentView: NSView

    init(content: NSView, header: NSView) {
        contentView = content
        super.init(frame: .zero)

        // -- outer container: explicit rounded corners on the glass card
        glassContainer.translatesAutoresizingMaskIntoConstraints = false
        glassContainer.cornerRadius = 24
        addSubview(glassContainer)

        // -- inner header: concentrically tracks the outer radius (no manual math)
        headerStrip.translatesAutoresizingMaskIntoConstraints = false
        headerStrip.wantsLayer = true
        headerStrip.addSubview(header)
        header.translatesAutoresizingMaskIntoConstraints = false
        glassContainer.addSubview(headerStrip)

        // -- body content
        contentView.translatesAutoresizingMaskIntoConstraints = false
        glassContainer.addSubview(contentView)

        NSLayoutConstraint.activate([
            glassContainer.leadingAnchor.constraint(equalTo: leadingAnchor),
            glassContainer.trailingAnchor.constraint(equalTo: trailingAnchor),
            glassContainer.topAnchor.constraint(equalTo: topAnchor),
            glassContainer.bottomAnchor.constraint(equalTo: bottomAnchor),

            headerStrip.leadingAnchor.constraint(equalTo: glassContainer.leadingAnchor),
            headerStrip.trailingAnchor.constraint(equalTo: glassContainer.trailingAnchor),
            headerStrip.topAnchor.constraint(equalTo: glassContainer.topAnchor),
            headerStrip.heightAnchor.constraint(equalToConstant: 52),

            header.leadingAnchor.constraint(equalTo: headerStrip.leadingAnchor, constant: 16),
            header.centerYAnchor.constraint(equalTo: headerStrip.centerYAnchor),

            contentView.leadingAnchor.constraint(equalTo: glassContainer.leadingAnchor, constant: 16),
            contentView.trailingAnchor.constraint(equalTo: glassContainer.trailingAnchor, constant: -16),
            contentView.topAnchor.constraint(equalTo: headerStrip.bottomAnchor, constant: 12),
            contentView.bottomAnchor.constraint(equalTo: glassContainer.bottomAnchor, constant: -16)
        ])
    }

    required init?(coder: NSCoder) {
        fatalError("init(coder:) has not been implemented")
    }
}

import AppKit

/// React to the *resolved* corner radii of a view whose corners are configured
/// via cornerConfiguration (e.g. .containerConcentric). Both `cornerConfiguration`
/// and `effectiveCornerRadii` are READ-ONLY: declare the configuration by
/// OVERRIDING the cornerConfiguration getter (never assign it), read the optional
/// `effectiveCornerRadii`, and override viewDidChangeEffectiveCornerRadii() to
/// update geometry-dependent drawing (shadow path, stroke, mask).
@MainActor
final class ConcentricBadgeView: NSView {
    // Declare the corner style by overriding the read-only getter.
    override var cornerConfiguration: NSViewCornerConfiguration? {
        .uniformCorners(radius: .containerConcentric)
    }

    override init(frame frameRect: NSRect) {
        super.init(frame: frameRect)
        wantsLayer = true
    }

    required init?(coder: NSCoder) { fatalError("init(coder:) has not been implemented") }

    override func viewDidChangeEffectiveCornerRadii() {
        super.viewDidChangeEffectiveCornerRadii()
        // effectiveCornerRadii is optional (nil when cornerConfiguration is nil).
        if let radii = effectiveCornerRadii {
            layer?.cornerRadius = radii.topLeft
        }
        needsDisplay = true
    }

    /// Force AppKit to recompute effectiveCornerRadii after a manual change that
    /// affects resolution (rare — most changes invalidate automatically).
    func refreshCorners() {
        invalidateCornerConfiguration()
    }
}

