/// Group several NSGlassEffectView instances inside an NSGlassEffectContainerView
/// so their glass is sampled and merged as one continuous surface, and nearby
/// shapes flow together. `spacing` controls how close two glass shapes must be
/// before they visually merge.
@available(macOS 26, *)
@MainActor
func makeMergedGlassToolbar(buttons: [NSView]) -> NSGlassEffectContainerView {
    let container = NSGlassEffectContainerView()
    container.spacing = 12  // merge glass shapes within 12pt of each other

    let row = NSStackView(views: buttons.map { content in
        let glass = NSGlassEffectView()
        glass.contentView = content
        glass.cornerRadius = 12
        return glass
    })
    row.orientation = .horizontal
    row.spacing = 8
    container.contentView = row
    return container
}

