/// Configure the Liquid Glass scroll-edge effect by setting
/// preferredScrollEdgeEffectStyle on a titlebar or split-view-item accessory
/// view controller (macOS 26.1+). The style controls how content fades/blurs
/// under the toolbar or sidebar header as it scrolls.
@available(macOS 26.1, *)
@MainActor
func installScrollEdgeAccessory(in window: NSWindow, sidebarItem: NSSplitViewItem) {
    // Titlebar accessory: hard edge keeps floating content crisp at the top.
    let titlebarAccessory = NSTitlebarAccessoryViewController()
    titlebarAccessory.layoutAttribute = .top
    titlebarAccessory.view = NSView()
    titlebarAccessory.preferredScrollEdgeEffectStyle = .hard
    window.addTitlebarAccessoryViewController(titlebarAccessory)

    // Sidebar accessory: soft edge gives the sidebar a gentle glass fade.
    let sidebarAccessory = NSSplitViewItemAccessoryViewController()
    sidebarAccessory.view = NSView()
    sidebarAccessory.preferredScrollEdgeEffectStyle = .soft
    sidebarItem.addTopAlignedAccessoryViewController(sidebarAccessory)
}

