/// Use NSVisualEffectView for semantic vibrancy materials (sidebars, header bars,
/// HUDs). Pick a `material` by role, choose a `blendingMode` (behindWindow blurs
/// the desktop/windows behind; withinWindow blurs sibling content), and let
/// `state` follow the window's active state so vibrancy dims when inactive.
@MainActor
final class SidebarBackgroundView: NSVisualEffectView {
    override init(frame frameRect: NSRect) {
        super.init(frame: frameRect)
        material = .sidebar               // semantic role, not a hardcoded color
        blendingMode = .behindWindow      // blur what's behind the window
        state = .followsWindowActiveState // dim when the window deactivates
    }

    required init?(coder: NSCoder) { fatalError("init(coder:) has not been implemented") }
}

