final class GestureRecognizersBasicsExample: NSViewController, NSGestureRecognizerDelegate {
    override func loadView() {
        view = NSView()
        let click = NSClickGestureRecognizer(target: self, action: #selector(clicked(_:)))
        click.numberOfClicksRequired = 1
        let pan = NSPanGestureRecognizer(target: self, action: #selector(panned(_:)))
        click.delegate = self
        pan.delegate = self
        view.addGestureRecognizer(click)
        view.addGestureRecognizer(pan)
    }

    func gestureRecognizer(_ gestureRecognizer: NSGestureRecognizer, shouldRecognizeSimultaneouslyWith otherGestureRecognizer: NSGestureRecognizer) -> Bool {
        gestureRecognizer is NSPanGestureRecognizer || otherGestureRecognizer is NSPanGestureRecognizer
    }

    @objc private func clicked(_ recognizer: NSClickGestureRecognizer) { }
    @objc private func panned(_ recognizer: NSPanGestureRecognizer) { }
}

