@MainActor
final class ControlEventsController: NSViewController {
    private let actionButton = NSButton(title: "Perform Action", target: nil, action: nil)
    private let slider = NSSlider(value: 50, minValue: 0, maxValue: 100, target: nil, action: nil)
    private let feedbackLabel = NSTextField(labelWithString: "Value: 50")

    override func loadView() {
        view = NSView(frame: NSRect(x: 0, y: 0, width: 400, height: 220))

        // Standard target-action wiring
        actionButton.target = self
        actionButton.action = #selector(buttonClicked(_:))

        // Register for a specific control event (macOS 11+)
        actionButton.addTarget(
            self,
            action: #selector(buttonTrackingEndedOutside(_:)),
            for: .trackingEndedOutside
        )

        // Continuous control fires its action repeatedly while tracking
        slider.isContinuous = true
        slider.target = self
        slider.action = #selector(sliderDragged(_:))

        for v in [actionButton, slider, feedbackLabel] {
            v.translatesAutoresizingMaskIntoConstraints = false
            view.addSubview(v)
        }

        NSLayoutConstraint.activate([
            actionButton.centerXAnchor.constraint(equalTo: view.centerXAnchor),
            actionButton.topAnchor.constraint(equalTo: view.topAnchor, constant: 30),

            slider.centerXAnchor.constraint(equalTo: view.centerXAnchor),
            slider.topAnchor.constraint(equalTo: actionButton.bottomAnchor, constant: 24),
            slider.widthAnchor.constraint(equalToConstant: 220),

            feedbackLabel.centerXAnchor.constraint(equalTo: view.centerXAnchor),
            feedbackLabel.topAnchor.constraint(equalTo: slider.bottomAnchor, constant: 16),
        ])
    }

    @objc private func buttonClicked(_ sender: NSButton) {
        feedbackLabel.stringValue = "Button clicked: \(sender.title)"
    }

    @objc private func buttonTrackingEndedOutside(_ sender: NSButton) {
        feedbackLabel.stringValue = "Released outside — action cancelled"
    }

    @objc private func sliderDragged(_ sender: NSSlider) {
        feedbackLabel.stringValue = "Value: \(sender.integerValue)"
    }

    /// Send an action programmatically, optionally through the responder chain.
    func triggerActionViaResponderChain() {
        // Passing nil as the target walks the responder chain.
        let didFire = actionButton.sendAction(
            actionButton.action,
            to: nil
        )
        feedbackLabel.stringValue = didFire
            ? "Action handled by responder chain"
            : "No responder handled the action"
    }
}

