@MainActor
final class AnchorDemoController: NSViewController {
    private let label = NSTextField(labelWithString: "Centered")
    private let box = NSView()

    override func loadView() {
        view = NSView(frame: NSRect(x: 0, y: 0, width: 480, height: 320))
        setupBox()
        setupLabel()
        activateConstraints()
    }

    private func setupBox() {
        box.wantsLayer = true
        box.layer?.backgroundColor = NSColor.controlAccentColor.withAlphaComponent(0.12).cgColor
        box.layer?.cornerRadius = 12
        box.translatesAutoresizingMaskIntoConstraints = false
        view.addSubview(box)
    }

    private func setupLabel() {
        label.font = .preferredFont(forTextStyle: .title2)
        label.alignment = .center
        label.translatesAutoresizingMaskIntoConstraints = false
        box.addSubview(label)
    }

    private func activateConstraints() {
        NSLayoutConstraint.activate([
            // Pin box inside the safe area with standard insets (mirrors readable rect).
            box.topAnchor.constraint(
                equalTo: view.safeAreaLayoutGuide.topAnchor,
                constant: 20
            ),
            box.leadingAnchor.constraint(
                equalTo: view.safeAreaLayoutGuide.leadingAnchor,
                constant: 20
            ),
            box.trailingAnchor.constraint(
                equalTo: view.safeAreaLayoutGuide.trailingAnchor,
                constant: -20
            ),
            box.bottomAnchor.constraint(
                equalTo: view.safeAreaLayoutGuide.bottomAnchor,
                constant: -20
            ),

            // Center the label inside the box.
            label.centerXAnchor.constraint(equalTo: box.centerXAnchor),
            label.centerYAnchor.constraint(equalTo: box.centerYAnchor)
        ])
    }
}

