@MainActor
final class TableViewDiffableDatasourceExample: NSViewController {
    enum Section { case main }
    struct Row: Hashable { let name: String }
    private let tableView = NSTableView()
    private lazy var dataSource = NSTableViewDiffableDataSource<Section, Row>(tableView: tableView) { tableView, column, row, item in
        let id = NSUserInterfaceItemIdentifier("Cell")
        let cell = tableView.makeView(withIdentifier: id, owner: self) as? NSTableCellView ?? NSTableCellView()
        cell.identifier = id
        cell.textField = NSTextField(labelWithString: item.name)
        return cell
    }

    func apply(rows: [Row]) {
        var snapshot = NSDiffableDataSourceSnapshot<Section, Row>()
        snapshot.appendSections([.main])
        snapshot.appendItems(rows, toSection: .main)
        dataSource.apply(snapshot, animatingDifferences: true)
    }
}

