// MARK: - Data Model

/// A navigation node in the sidebar outline — trivially Sendable so it crosses
/// the actor boundary cleanly when the selection feeds the inspector.
struct SidebarNode: Sendable {
    let title: String
    let icon: String // SF Symbol systemName
    let children: [SidebarNode]

    init(_ title: String, icon: String, children: [SidebarNode] = []) {
        self.title = title
        self.icon = icon
        self.children = children
    }

    var isGroup: Bool { !children.isEmpty }
}

// MARK: - Root Split View Controller

/// Drives the three-pane split layout. Owns the sidebar, content list, and
/// inspector children. Because NSSplitViewController conforms to NSResponder,
/// `toggleSidebar(_:)` participates in the responder chain automatically —
/// wire it to View > Show/Hide Sidebar (⌃⌘S) or a toolbar item.
@MainActor
final class MainSplitController: NSSplitViewController {

    // Child controllers are kept as properties so the split view items
    // retain them; destroying the controller deallocates the pane.
    private let sidebarController = SidebarController()
    private let contentController = ContentController()
    private let inspectorController = InspectorController()

    // Split view items held for programmatic collapse checks.
    private var sidebarItem: NSSplitViewItem!
    private var inspectorItem: NSSplitViewItem!

    // MARK: - Lifecycle

    override func viewDidLoad() {
        super.viewDidLoad()

        // --- Sidebar (left) ---
        // init(sidebarWithViewController:) sets behavior = .sidebar, giving the
        // pane the system-standard source-list appearance and thinner divider.
        let sidebar = NSSplitViewItem(sidebarWithViewController: sidebarController)
        sidebar.allowsFullHeightLayout = true   // macOS 11.0+: sidebar extends
                                                 // behind the titlebar when the
                                                 // window uses a unified toolbar.
        sidebar.minimumThickness = 180
        sidebar.maximumThickness = 320
        sidebar.preferredThicknessFraction = 0.22
        sidebar.canCollapse = true
        self.sidebarItem = sidebar

        // --- Content list (center) ---
        // init(contentListWithViewController:) sets behavior = .contentList, which
        // styles the divider between sidebar and content like Finder's list pane.
        let content = NSSplitViewItem(contentListWithViewController: contentController)
        content.minimumThickness = 260
        // Preferred fraction is measured against the remaining width after
        // fixed-thickness panes (sidebar + inspector) claim their space.
        content.preferredThicknessFraction = 0.52

        // --- Inspector (right) ---
        let inspector = NSSplitViewItem(inspectorWithViewController: inspectorController)
        inspector.minimumThickness = 220
        inspector.maximumThickness = 400
        inspector.canCollapse = true
        // Collapse the inspector initially if the selection carries no detail.
        inspector.isCollapsed = false
        self.inspectorItem = inspector

        addSplitViewItem(sidebar)
        addSplitViewItem(content)
        addSplitViewItem(inspector)

        // Forward sidebar selection changes to both the content area and the
        // inspector so they stay in sync.
        sidebarController.onSelectionChanged = { [weak self] node in
            self?.contentController.show(node: node)
            self?.inspectorController.inspect(node: node)
        }
    }

    // MARK: - Sidebar Toggle (First Responder / Toolbar)

    /// Toggle the sidebar's collapsed state. NSSplitViewController's built-in
    /// `toggleSidebar(_:)` walks splitViewItems and collapses the first item
    /// whose behavior is `.sidebar`. Override only if you need custom logic.
    @IBAction override func toggleSidebar(_ sender: Any?) {
        super.toggleSidebar(sender)
        // After the built-in toggle, synchronize toolbar state if needed.
        // NSToolbar validates items against the first responder, so a
        // toolbar item bound to toggleSidebar: updates its state automatically.
    }

    /// Programmatically reveal or hide the inspector.
    func setInspectorVisible(_ visible: Bool, animated: Bool = true) {
        guard inspectorItem.isCollapsed == visible else { return }
        if animated {
            inspectorItem.animator().isCollapsed = !visible
        } else {
            inspectorItem.isCollapsed = !visible
        }
    }
}

