@MainActor
final class SidebarController: NSViewController, NSOutlineViewDelegate, NSOutlineViewDataSource {

    /// Fires whenever the user selects a sidebar row.
    var onSelectionChanged: ((SidebarNode) -> Void)?

    private let scrollView = NSScrollView()
    private let outlineView = NSOutlineView()

    private let roots: [SidebarNode] = [
        SidebarNode("Library", icon: "books.vertical", children: [
            SidebarNode("All Photos", icon: "photo.on.rectangle"),
            SidebarNode("Albums", icon: "rectangle.stack"),
            SidebarNode("Shared", icon: "person.2"),
        ]),
        SidebarNode("Devices", icon: "externaldrive", children: [
            SidebarNode("Macintosh HD", icon: "internaldrive"),
            SidebarNode("External SSD", icon: "externaldrive.badge.plus"),
        ]),
        SidebarNode("Tags", icon: "tag", children: [
            SidebarNode("Red", icon: "circle.fill"),
            SidebarNode("Blue", icon: "circle.fill"),
        ]),
    ]

    override func loadView() {
        view = NSView()
        configureOutline()
    }

    private func configureOutline() {
        // Source-list style: sets the table style to .sourceList for translucent
        // background, row selection highlight, and automatic vibrancy blending.
        // Replaces the deprecated .selectionHighlightStyle = .sourceList
        // (macOS 12+ deprecated).
        outlineView.style = .sourceList
        outlineView.indentationPerLevel = 14
        outlineView.headerView = nil
        outlineView.delegate = self
        outlineView.dataSource = self

        let column = NSTableColumn(identifier: NSUserInterfaceItemIdentifier("SidebarColumn"))
        column.resizingMask = .autoresizingMask
        outlineView.addTableColumn(column)
        outlineView.outlineTableColumn = column

        scrollView.documentView = outlineView
        scrollView.hasVerticalScroller = true
        scrollView.drawsBackground = false
        scrollView.borderType = .noBorder
        scrollView.translatesAutoresizingMaskIntoConstraints = false
        view.addSubview(scrollView)

        NSLayoutConstraint.activate([
            scrollView.leadingAnchor.constraint(equalTo: view.leadingAnchor),
            scrollView.trailingAnchor.constraint(equalTo: view.trailingAnchor),
            scrollView.topAnchor.constraint(equalTo: view.topAnchor),
            scrollView.bottomAnchor.constraint(equalTo: view.bottomAnchor),
        ])
    }

    // MARK: - NSOutlineViewDataSource

    func outlineView(_ outlineView: NSOutlineView, numberOfChildrenOfItem item: Any?) -> Int {
        guard let node = item as? SidebarNode else { return roots.count }
        return node.children.count
    }

    func outlineView(_ outlineView: NSOutlineView, child index: Int, ofItem item: Any?) -> Any {
        guard let node = item as? SidebarNode else { return roots[index] }
        return node.children[index]
    }

    func outlineView(_ outlineView: NSOutlineView, isItemExpandable item: Any) -> Bool {
        return (item as? SidebarNode)?.isGroup ?? false
    }

    func outlineView(_ outlineView: NSOutlineView, isGroupItem item: Any) -> Bool {
        return (item as? SidebarNode)?.isGroup ?? false
    }

    // MARK: - NSOutlineViewDelegate

    func outlineView(_ outlineView: NSOutlineView, viewFor tableColumn: NSTableColumn?, item: Any) -> NSView? {
        guard let node = item as? SidebarNode else { return nil }

        let cellID = NSUserInterfaceItemIdentifier("SidebarCell")
        let cell = outlineView.makeView(withIdentifier: cellID, owner: self)
            as? NSTableCellView
            ?? {
                let c = NSTableCellView()
                let field = NSTextField(labelWithString: "")
                field.translatesAutoresizingMaskIntoConstraints = false
                c.addSubview(field)
                c.textField = field
                c.identifier = cellID
                NSLayoutConstraint.activate([
                    field.leadingAnchor.constraint(equalTo: c.leadingAnchor, constant: 4),
                    field.centerYAnchor.constraint(equalTo: c.centerYAnchor),
                ])
                return c
            }()

        cell.textField?.stringValue = node.title
        cell.imageView?.image = NSImage(systemSymbolName: node.icon, accessibilityDescription: node.title)
        return cell
    }

    func outlineViewSelectionDidChange(_ notification: Notification) {
        let row = outlineView.selectedRow
        guard row >= 0, let node = outlineView.item(atRow: row) as? SidebarNode else { return }
        onSelectionChanged?(node)
    }
}

