/// Declare toolbar identifiers in an extension so they're typed, discoverable,
/// and safe from string-typo drift. Use reverse-DNS prefixes for custom items;
/// system identifiers live on NSToolbarItem.Identifier directly.
extension NSToolbarItem.Identifier {
