// MARK: - Window Controller

/// A window controller that configures a customizable toolbar via
/// NSToolbarDelegate. The controller owns the toolbar setup and
/// handles actions dispatched by toolbar items through the responder chain.
@MainActor
final class EditorWindowController: NSWindowController {

    // MARK: - Toolbar Setup

    override func windowDidLoad() {
        super.windowDidLoad()
        configureToolbar()
    }

    private func configureToolbar() {
        // NSToolbar's own identifier is an NSToolbar.Identifier (a String) and
        // is distinct from the NSToolbarItem.Identifier values that name items.
        let toolbar = NSToolbar(identifier: "EditorToolbar")
        toolbar.delegate = self
        toolbar.allowsUserCustomization = true
        toolbar.autosavesConfiguration = true
        toolbar.displayMode = .iconAndLabel
        toolbar.sizeMode = .regular
        window?.toolbar = toolbar
    }

    // MARK: - Toolbar Actions

    @objc private func addDocument(_ sender: NSToolbarItem) {
        // Action dispatched when the user clicks the Add toolbar item.
        print("Add new document — dispatched from toolbar item:", sender.itemIdentifier.rawValue)
    }

    @objc private func shareDocument(_ sender: NSToolbarItem) {
        let picker = NSSharingServicePicker(items: ["Shared content"])
        guard let view = sender.view else { return }
        picker.show(relativeTo: view.bounds, of: view, preferredEdge: .minY)
    }
}

// MARK: - NSToolbarDelegate

extension EditorWindowController: NSToolbarDelegate {

    /// Vends an NSToolbarItem for each identifier the toolbar asks for.
    /// Called once per identifier when the toolbar first loads, and again
    /// when the user customizes the toolbar via the customization palette.
    func toolbar(
        _ toolbar: NSToolbar,
        itemForItemIdentifier itemIdentifier: NSToolbarItem.Identifier,
        willBeInsertedIntoToolbar flag: Bool
    ) -> NSToolbarItem? {
        switch itemIdentifier {
        case .toggleSidebar:
            let item = NSToolbarItem(itemIdentifier: itemIdentifier)
            item.label = "Sidebar"
            item.paletteLabel = "Toggle Sidebar"
            item.image = NSImage(
                systemSymbolName: "sidebar.left",
                accessibilityDescription: "Show or hide the sidebar"
            )
            item.action = #selector(NSSplitViewController.toggleSidebar(_:))
            // isNavigational marks this item as a navigation control; AppKit
            // may style it visually distinct and optimize responder-chain
            // resolution for standard sidebar toggle behavior.
            item.isNavigational = true
            return item

        case .addDocument:
            let item = NSToolbarItem(itemIdentifier: itemIdentifier)
            item.label = "Add"
            item.paletteLabel = "Add Document"
            item.image = NSImage(
                systemSymbolName: "plus",
                accessibilityDescription: "Create a new document"
            )
            item.action = #selector(addDocument(_:))
            item.target = self
            return item

        case .share:
            let item = NSToolbarItem(itemIdentifier: itemIdentifier)
            item.label = "Share"
            item.paletteLabel = "Share Document"
            item.image = NSImage(
                systemSymbolName: "square.and.arrow.up",
                accessibilityDescription: "Share this document"
            )
            item.action = #selector(shareDocument(_:))
            item.target = self
            return item

        case .inspector:
            let item = NSToolbarItem(itemIdentifier: itemIdentifier)
            item.label = "Inspector"
            item.paletteLabel = "Show Inspector"
            item.image = NSImage(
                systemSymbolName: "sidebar.right",
                accessibilityDescription: "Show or hide the inspector"
            )
            item.action = #selector(toggleInspector(_:))
            item.target = self
            item.isNavigational = true
            return item

        case .fontPanel:
            let item = NSToolbarItem(itemIdentifier: itemIdentifier)
            item.label = "Fonts"
            item.paletteLabel = "Show Fonts"
            item.image = NSImage(
                systemSymbolName: "textformat",
                accessibilityDescription: "Open the Font panel"
            )
            item.action = #selector(NSFontManager.orderFrontFontPanel(_:))
            return item

        case .print:
            let item = NSToolbarItem(itemIdentifier: itemIdentifier)
            item.label = "Print"
            item.paletteLabel = "Print Document"
            item.image = NSImage(
                systemSymbolName: "printer",
                accessibilityDescription: "Print the current document"
            )
            item.action = #selector(NSDocument.printDocument(_:))
            return item

        default:
            return nil
        }
    }

    /// The ordered set of identifiers shown when the toolbar first appears
    /// or after the user resets customization to defaults.
    func toolbarDefaultItemIdentifiers(_ toolbar: NSToolbar) -> [NSToolbarItem.Identifier] {
        [
            .toggleSidebar,
            .flexibleSpace,
            .addDocument,
            .share,
            .space,
            .inspector,
            .fontPanel,
            .flexibleSpace,
            .print
        ]
    }

    /// Every identifier the user is permitted to add to the toolbar via the
    /// customization palette. Items here but not in the default set appear
    /// in the palette drawer for drag-in.
    func toolbarAllowedItemIdentifiers(_ toolbar: NSToolbar) -> [NSToolbarItem.Identifier] {
        [
            .toggleSidebar,
            .addDocument,
            .share,
            .inspector,
            .fontPanel,
            .print,
            .flexibleSpace,
            .space,
            .sidebarTrackingSeparator
        ]
    }

    /// Items that participate in a mutually exclusive selection group — only
    /// one can be selected at a time. Omit this delegate method when the
    /// toolbar has no selectable items.
    func toolbarSelectableItemIdentifiers(_ toolbar: NSToolbar) -> [NSToolbarItem.Identifier] {
        // No selectable items in this toolbar.
        []
    }

    // MARK: - Inspector Toggle Action

    @objc private func toggleInspector(_ sender: NSToolbarItem) {
        // Dispatch a toggle-inspector command through the responder chain
        // so the active split view controller or inspector owner handles it.
        NSApp.sendAction(#selector(toggleInspector(_:)), to: nil, from: sender)
    }
}

