// MARK: - Async NSAlert sheet presenter

/// Extends NSAlert with a Swift concurrency bridge that presents the alert
/// as a sheet on the key window and suspends the calling task until the user
/// dismisses it. The returned ModalResponse can be checked to determine which
/// button the user clicked.
extension NSAlert {
    /// Present this alert as a window-modal sheet and await the user's response.
    ///
    /// - Parameter window: The parent window the sheet attaches to. If `nil`,
    ///   falls back to `NSApp.keyWindow`. A sheet MUST have a parent window;
    ///   calling this when no window is available is a programmer error.
    /// - Returns: The `NSApplication.ModalResponse` identifying the button the
    ///   user clicked, or `.abort` (1000) if the window closed before dismissal.
    @MainActor
    func runSheetModal(on window: NSWindow? = nil) async -> NSApplication.ModalResponse {
        guard let parentWindow = window ?? NSApp.keyWindow else {
            return .abort
        }
        return await withCheckedContinuation { continuation in
            self.beginSheetModal(for: parentWindow) { response in
                continuation.resume(returning: response)
            }
        }
    }
}

// MARK: - Usage example

/// Demonstrates an async NSAlert sheet: a destructive-action confirmation
/// with a "Don't ask again" suppression checkbox, a custom icon, and
/// an informative accessory view showing affected items.
@MainActor
func confirmDestructiveAction(on window: NSWindow? = nil) async -> Bool {
    // Build the alert.
    let alert = NSAlert()
    alert.messageText = "Permanently Delete Items"
    alert.informativeText = """
        You are about to delete 3 items. This action cannot be undone. \
        The items will be removed immediately and will not be placed in the Trash.
        """
    alert.alertStyle = .critical

    // Buttons: first added = default / rightmost (Return key activates it).
    alert.addButton(withTitle: "Delete")
    alert.addButton(withTitle: "Cancel")

    // Suppression checkbox — native AppKit suppression, not a custom checkbox.
    alert.showsSuppressionButton = true
    alert.suppressionButton?.title = "Do not warn me about deleting items"
    alert.suppressionButton?.state = .off

    // Optional: a bespoke icon. If nil, AppKit uses the app icon.
    alert.icon = NSImage(
        systemSymbolName: "trash",
        accessibilityDescription: "Trash icon"
    )

    // Optional accessory view — e.g. a list of affected items.
    let detailField = NSTextField(wrappingLabelWithString: "• report-q2.pdf\n• draft-notes.txt\n• screenshot.png")
    detailField.isEditable = false
    detailField.drawsBackground = false
    detailField.font = NSFont.systemFont(ofSize: NSFont.smallSystemFontSize)
    detailField.frame.size = detailField.fittingSize
    alert.accessoryView = detailField

    // Present as a sheet and await the user's choice.
    let response = await alert.runSheetModal(on: window)

    // Persist the suppression preference.
    if alert.suppressionButton?.state == .on {
        UserDefaults.standard.set(true, forKey: "suppressDestructiveDeleteWarning")
    }

    return response == .alertFirstButtonReturn
}

// MARK: - Guard with suppression check

/// Check the suppression flag BEFORE calling confirmDestructiveAction.
/// Wraps the pattern end-to-end: guard, present if needed, act on result.
@MainActor
func deleteItemsIfConfirmed(on window: NSWindow? = nil) async {
    let suppressed = UserDefaults.standard.bool(forKey: "suppressDestructiveDeleteWarning")
    guard !suppressed else {
        // User previously opted out — proceed without showing the alert.
        performDeletion()
        return
    }

    let confirmed = await confirmDestructiveAction(on: window)
    if confirmed {
        performDeletion()
    }
}

@MainActor
private func performDeletion() {
    // Actual deletion logic here.
    print("Items deleted.")
}

