// MARK: - Popover content view controller

/// Lightweight content controller for a transient popover. Keeps a dismiss
/// callback so the popover can be closed programmatically after a selection,
/// matching the HIG guidance that a popover should close when people select
/// an item in it.
@MainActor
final class PopoverContentController: NSViewController {

    var onDismiss: (() -> Void)?

    private let titleLabel = NSTextField(labelWithString: "Choose an option")
    private let option1Button = NSButton(title: "Option A", target: nil, action: nil)
    private let option2Button = NSButton(title: "Option B", target: nil, action: nil)

    override func loadView() {
        view = NSView(frame: NSRect(x: 0, y: 0, width: 200, height: 120))

        titleLabel.font = .preferredFont(forTextStyle: .headline)
        titleLabel.alignment = .center

        option1Button.bezelStyle = .rounded
        option1Button.target = self
        option1Button.action = #selector(optionSelected(_:))

        option2Button.bezelStyle = .rounded
        option2Button.target = self
        option2Button.action = #selector(optionSelected(_:))

        let stack = NSStackView(views: [titleLabel, option1Button, option2Button])
        stack.orientation = .vertical
        stack.alignment = .centerX
        stack.distribution = .equalSpacing
        stack.spacing = 12
        stack.translatesAutoresizingMaskIntoConstraints = false
        view.addSubview(stack)

        NSLayoutConstraint.activate([
            stack.centerXAnchor.constraint(equalTo: view.centerXAnchor),
            stack.centerYAnchor.constraint(equalTo: view.centerYAnchor),
            stack.widthAnchor.constraint(equalToConstant: 180),
        ])
    }

    @objc private func optionSelected(_ sender: NSButton) {
        titleLabel.stringValue = "Selected: \(sender.title)"
        // Close the popover after a brief delay so the user sees the feedback.
        DispatchQueue.main.asyncAfter(deadline: .now() + 0.3) { [weak self] in
            self?.onDismiss?()
        }
    }
}

// MARK: - Host view controller that shows the popover

/// Demonstrates anchoring a transient NSPopover to a button. The popover
/// appears with an arrow pointing toward the button and dismisses when the
/// user clicks anywhere outside the popover bounds.
@MainActor
final class PopoverDemoController: NSViewController {

    private let popover = NSPopover()
    private let showButton = NSButton(title: "Show Popover", target: nil, action: nil)

    override func loadView() {
        view = NSView(frame: NSRect(x: 0, y: 0, width: 320, height: 200))

        showButton.bezelStyle = .rounded
        showButton.target = self
        showButton.action = #selector(togglePopover(_:))
        showButton.translatesAutoresizingMaskIntoConstraints = false
        view.addSubview(showButton)

        // Configure the popover once.
        popover.behavior = .transient
        popover.animates = true

        let contentController = PopoverContentController()
        contentController.onDismiss = { [weak self] in
            self?.popover.performClose(nil)
        }
        popover.contentViewController = contentController

        NSLayoutConstraint.activate([
            showButton.centerXAnchor.constraint(equalTo: view.centerXAnchor),
            showButton.centerYAnchor.constraint(equalTo: view.centerYAnchor),
        ])
    }

    @objc private func togglePopover(_ sender: NSButton) {
        if popover.isShown {
            popover.performClose(sender)
        } else {
            // show(relativeTo:of:preferredEdge:) anchors the popover's arrow
            // to the button's bounds and prefers the specified edge.
            popover.show(
                relativeTo: sender.bounds,
                of: sender,
                preferredEdge: .maxY
            )
        }
    }
}

