// MARK: - @main Entry Point

/// The `@main` attribute marks this type as the program's entry point.
/// AppKit apps must conform to `NSApplicationDelegate` (a subclass of
/// `NSObject`) and implement the required static `main()` method, which
/// creates the shared application, sets its delegate, and starts the
/// run loop. This is the canonical Swift 6 replacement for the legacy
/// `NSApplicationMain(_:_:)` C function and standalone `main.swift`.
///
/// The delegate and all its methods run on `@MainActor` — AppKit's entire
/// UI lifecycle is main-thread-bound, and Swift 6 enforces this through
/// global-actor isolation on the delegate class.
@main
@MainActor
final class AppDelegate: NSObject, NSApplicationDelegate {

    // MARK: - Entry Point

    /// Required by the `@main` protocol conformance. Create the shared
    /// `NSApplication` instance, assign the delegate, and call `run()`.
    /// All three steps must happen in this exact order.
    static func main() {
        let app = NSApplication.shared
        let delegate = AppDelegate()
        app.delegate = delegate

        // Set the activation policy BEFORE calling run(). `.regular`
        // gives the app a Dock icon and a menu bar — the standard
        // configuration for a foreground GUI app. Use `.accessory` or
        // `.prohibited` for background/agent processes.
        app.setActivationPolicy(.regular)

        app.run()
    }

    // MARK: - Lifecycle

    /// Fired after the app finishes launching. This is the primary setup
    /// hook — create windows, register defaults, warm caches, and restore
    /// state. The HIG mandates that apps should "appear quickly and be
    /// ready to use" with no splash screens or configuration wizards
    /// blocking this callback.
    func applicationDidFinishLaunching(_ notification: Notification) {
        // Create and show the main window. Long-running setup should be
        // offloaded to a background Task to avoid blocking the first frame.
        let windowController = MainWindowController()
        windowController.showWindow(nil)

        // Store the window controller somewhere the delegate retains —
        // a local variable would deallocate when this method returns,
        // closing the window immediately.
        windowControllers.append(windowController)

        // Perform one-time setup. For heavy work (database migration,
        // network pre-warming), spawn a Task so the window appears first.
        Task {
            await warmCaches()
        }
    }

    /// Fired when the app is about to become active — the user clicked the
    /// Dock icon, switched from another app, or the app launched into the
    /// foreground. Use this to re-fetch data, resume animations, or
    /// re-enable menu items that were dimmed while inactive.
    func applicationDidBecomeActive(_ notification: Notification) {
        // Re-enable UI that was dimmed while inactive. Avoid re-running
        // the full launch setup — applicationDidFinishLaunching already
        // handled one-time initialization.
    }

    /// Last-chance cleanup before the process exits. Invalidate timers,
    /// close network connections, remove temporary files. Do NOT start
    /// new async work here — the app will exit when this method returns.
    func applicationWillTerminate(_ notification: Notification) {
        // Synchronous teardown only.
    }

    // MARK: - Window Management

    /// Retain window controllers so they are not deallocated when they
    /// go out of scope. A window controller that is deallocated closes
    /// its window automatically.
    private var windowControllers: [NSWindowController] = []

    /// Helper for warming caches on a background actor. Real apps replace
    /// this with actual async I/O.
    private func warmCaches() async {
        // Simulated cache warm — replace with real work.
        try? await Task.sleep(nanoseconds: 100_000_000) // 0.1 s
    }
}

