// MARK: - Application delegate with deferred termination support

/// Manages application termination by holding outstanding async work and
/// calling reply(toApplicationShouldTerminate:) once all work completes.
@MainActor
final class AppDelegate: NSObject, NSApplicationDelegate {

    /// Set to `true` while work is in flight that must finish before termination.
    /// When `applicationShouldTerminate(_:)` returns `.terminateLater` and this
    /// flag is set, the reply is deferred until the work completes.
    private var hasPendingWork = false

    /// Invocation counter so only the final work batch replies — avoids
    /// double-replying if multiple work items overlap.
    private var pendingWorkCount = 0

    // MARK: - Termination hooks

    /// Called when the user chooses Quit (Cmd-Q), the Dock menu Quit item,
    /// or the system requests termination (logout/restart/shutdown).
    ///
    /// Return `.terminateLater` to defer the quit decision until async work
    /// finishes. Return `.terminateCancel` to refuse termination (e.g., a
    /// "Save changes?" dialog was dismissed with Cancel). Return `.terminateNow`
    /// when no work is pending and termination can proceed immediately.
    func applicationShouldTerminate(_ sender: NSApplication) -> NSApplication.TerminateReply {
        if hasPendingWork {
            // Work already in flight — the deferred completion handler will
            // call reply(toApplicationShouldTerminate:) when ready.
            return .terminateLater
        }

        // If you need confirmation (unsaved documents, etc.), present a sheet
        // or alert here. On confirm, begin the async work and return .terminateLater.
        // On cancel, return .terminateCancel.

        // No pending work — allow immediate termination.
        return .terminateNow
    }

    /// Control whether the app quits when the last window is closed.
    /// Returning `false` keeps the app running (standard for document-based
    /// apps that may reopen windows). Returning `true` exits when the last
    /// window closes (standard for single-window utility apps).
    func applicationShouldTerminateAfterLastWindowClosed(_ sender: NSApplication) -> Bool {
        // Return `false` for document-based apps that stay alive menu-bar-only.
        // Return `true` for single-window utilities that should exit naturally.
        false
    }

    // MARK: - Deferred termination workflow

    /// Example entry point: start async work that must complete before quitting.
    /// Real apps replace this body with actual async I/O — flushing a database,
    /// uploading final state, or writing a document to disk.
    func beginDeferredTerminationWork() {
        pendingWorkCount += 1
        hasPendingWork = true

        Task { [pendingWorkCount, weak self] in
            // Simulated async work (replace with real I/O).
            try? await Task.sleep(nanoseconds: 500_000_000) // 0.5 s

            await self?.workItemCompleted(batch: pendingWorkCount)
        }
    }

    /// Called when each work item finishes. When the count reaches zero,
    /// replies to the termination request with the final decision.
    private func workItemCompleted(batch: Int) {
        pendingWorkCount -= 1
        guard pendingWorkCount <= 0 else { return }

        hasPendingWork = false
        pendingWorkCount = 0

        // Notify AppKit that termination may now proceed (or be refused).
        NSApp.reply(toApplicationShouldTerminate: true)
    }

    // MARK: - Modal window protection

    /// Demonstrates the interaction between modal windows and termination.
    /// By default, `NSWindow.preventsApplicationTerminationWhenModal` is
    /// `true`, so a modal sheet shown during quit will pause termination
    /// without any additional code. Set the property to `false` on windows
    /// that should not block quit (e.g., a progress window that can safely
    /// be torn down).
    func configureProgressWindow(_ window: NSWindow) {
        // Allow termination to proceed even when this window is modal — it
        // represents non-critical progress that can be safely abandoned.
        window.preventsApplicationTerminationWhenModal = false
    }

    // MARK: - Cleanup on actual termination

    func applicationWillTerminate(_ notification: Notification) {
        // Perform last-chance cleanup: invalidate timers, close sockets,
        // remove temporary files. Do NOT start new async work here — the
        // app will exit when this method returns.
        hasPendingWork = false
        pendingWorkCount = 0
    }
}

